const mexicoTreasureData=[{"name":"Chichén Itzá","subtitle":"Ancient wonder","description":"An ancient Maya city celebrated for the stepped Temple of Kukulcán and its remarkable ceremonial monuments.","region":"Yucatán · Tinum municipality","lat":20.6843,"lon":-88.5678},{"name":"El Arco","subtitle":"Sea & stone","description":"A natural granite arch rising from the sea at Land’s End, the dramatic southern tip of the Baja California peninsula.","region":"Baja California Sur · Los Cabos municipality","lat":22.876,"lon":-109.8947},{"name":"Zócalo","subtitle":"Historic Mexico City","description":"Mexico City’s grand central plaza, framed by the Metropolitan Cathedral and National Palace in the historic centre.","region":"Mexico City · Cuauhtémoc borough","lat":19.4326,"lon":-99.1332}];
