function countryTreasures(key){if(key!=='mexico')return '';return '<section class="mexico-treasures" aria-label="Mexico treasures"><p class="treasures-label">TREASURES OF MEXICO</p><div class="treasure-badges">'+mexicoTreasureData.map((t,i)=>'<button type="button" class="treasure-badge" data-treasure="'+i+'" aria-label="Discover '+t.name+'" aria-pressed="false">'+mexicoTreasureIcons[i]+'<span class="treasure-caption"><strong>'+t.name+'</strong><span>'+t.subtitle+'</span></span></button>').join('')+'</div></section>';}
function setupTreasureDetails(){
 document.querySelectorAll('[data-treasure]').forEach(button=>button.onclick=()=>{
  document.querySelectorAll('[data-treasure]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});
  let popup=document.querySelector('#treasure-dialog');if(!popup){popup=document.createElement('dialog');popup.id='treasure-dialog';popup.setAttribute('aria-labelledby','treasure-title');document.body.append(popup);popup.addEventListener('click',e=>{const r=popup.getBoundingClientRect();if(e.target===popup&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))popup.close();});}
  const t=mexicoTreasureData[Number(button.dataset.treasure)];
  popup.innerHTML='<button type="button" class="treasure-close" aria-label="Close treasure details">×</button><h3 id="treasure-title">'+t.name+'</h3><p>'+t.description+'</p><p class="treasure-region">'+t.region+'</p><dl><div><dt>Latitude</dt><dd>'+t.lat.toFixed(4)+'°</dd></div><div><dt>Longitude</dt><dd>'+t.lon.toFixed(4)+'°</dd></div></dl><span class="coordinate-note">Approximate landmark location</span>';
  popup.querySelector('.treasure-close').onclick=()=>popup.close();popup.showModal();
 });
}
